<script setup>
import {computed,ref,onMounted,onBeforeUnmount} from 'vue';
import {request} from './api.js';
import {displayValue} from './catalog.js';
import {phase} from './model.js';
import {downloadJson} from './skins.js';
import PanelDialog from './PanelDialog.vue';
const props=defineProps({project:String,kind:{type:String,default:'episodes'}});
const emit=defineEmits(['replay','studio','candidate']);
const rows=ref([]),total=ref(null),cursor=ref(null),query=ref(''),filter=ref(''),loading=ref(false),error=ref(''),notice=ref('');
const detail=ref(null),dialog=ref(false),detailLoading=ref(false),detailError=ref(''),events=ref([]),eventCursor=ref(null),eventTotal=ref(null),eventType=ref(props.kind==='actions'?'action':''),eventLoading=ref(false),saving=ref(false),candidate=ref(false),name=ref(''),purpose=ref(''),selected=ref([]),comparison=ref(null);
const pendingCandidate=ref(null);
let generation=0,detailGeneration=0,eventGeneration=0;
/** 运行页读取运行目录，其他证据页读取Episode目录。 Resolve the appropriate evidence collection. */
const collection=computed(()=>props.kind==='runs'?'simulation-runs':'episodes');
/** 按工作任务提供清晰页名。 Name the evidence page for its task. */
const title=computed(()=>({runs:'仿真运行',episodes:'观测与实验库',actions:'动作与执行回执'}[props.kind]));
/** 查询服务端分页及筛选，隔离迟到响应。 Query server pagination and filters while isolating stale responses. */
async function load(append=false){if(append&&(!cursor.value||loading.value))return;const ticket=++generation;loading.value=true;error.value='';if(!append){rows.value=[];cursor.value=null;total.value=null;selected.value=[];comparison.value=null;}const params=new URLSearchParams({pageSize:'20'});if(query.value.trim())params.set('q',query.value.trim());if(filter.value)params.set(props.kind==='runs'?'status':'executionMode',filter.value);if(append)params.set('cursor',cursor.value);try{const result=await request('/'+collection.value+'?'+params,props.project);if(ticket!==generation)return;rows.value=append?[...rows.value,...result.items]:result.items;cursor.value=result.nextCursor;total.value=result.total;}catch(cause){if(ticket===generation)error.value=cause.message;}finally{if(ticket===generation)loading.value=false;}}
/** 从当前筛选重新查询。 Reload the current filter. */
function reload(){load();}
/** 保留现有结果追加下一页。 Append the next result page. */
function more(){load(true);}
/** 打开封存实验详情。 Open sealed episode detail. */
async function open(item){const id=props.kind==='runs'?item.episodeId:item.id;if(!id)return;const ticket=++detailGeneration;++eventGeneration;dialog.value=true;detailLoading.value=true;detail.value=null;events.value=[];eventCursor.value=null;detailError.value='';candidate.value=false;comparison.value=null;try{const result=await request('/episodes/'+encodeURIComponent(id),props.project);if(ticket!==detailGeneration)return;detail.value=result;await loadEvents();}catch(cause){if(ticket===detailGeneration)detailError.value=cause.message;}finally{if(ticket===detailGeneration)detailLoading.value=false;}}
/** 分页读取真实事件类型；筛选变化使旧游标失效。 Page actual event types, invalidating old cursors after filter changes. */
async function loadEvents(append=false){if(!detail.value||append&&(!eventCursor.value||eventLoading.value))return;const ticket=++eventGeneration;eventLoading.value=true;detailError.value='';if(!append){events.value=[];eventCursor.value=null;eventTotal.value=null;}const params=new URLSearchParams({pageSize:'15'});if(eventType.value)params.set('type',eventType.value);if(append)params.set('cursor',eventCursor.value);try{const result=await request('/episodes/'+encodeURIComponent(detail.value.id)+'/events?'+params,props.project);if(ticket!==eventGeneration)return;events.value=append?[...events.value,...result.items]:result.items;eventCursor.value=result.nextCursor;eventTotal.value=result.total;}catch(cause){if(ticket===eventGeneration)detailError.value=cause.message;}finally{if(ticket===eventGeneration)eventLoading.value=false;}}
/** 切换事件类型时重新读取第一页。 Read the first page when event type changes. */
function filterEvents(){loadEvents();}
/** 继续读取已封存事件。 Continue loading sealed events. */
function moreEvents(){loadEvents(true);}
/** 表单未保存时请求明确放弃，写请求未完成时不离开。 Resolve unsaved forms explicitly and stay during pending writes. */
function canLeave(){return !saving.value&&(!candidate.value||!name.value&&!purpose.value||window.confirm(pendingCandidate.value?'候选保存结果尚未确认，可能已在数据交接页生成。离开后请先查看已有记录，确认离开？':'数据候选尚未保存，放弃填写并离开？'));}
/** 关闭详情使异步响应失效。 Close detail and invalidate pending reads. */
function close(){if(!canLeave())return;++detailGeneration;++eventGeneration;dialog.value=false;detail.value=null;candidate.value=false;}
/** 从详情打开原始关键帧回放。 Open the original keyframe playback from detail. */
function replay(){if(detail.value&&canLeave())emit('replay',detail.value.id);}
/** 导出服务端生成的授权索引。 Export the authorized index generated by the server. */
async function exportEpisode(){if(!detail.value||saving.value)return;saving.value=true;detailError.value='';try{const result=await request('/episodes/'+encodeURIComponent(detail.value.id)+'/export',props.project);downloadJson(detail.value.id+'.json',result);}catch(cause){detailError.value=cause.message;}finally{saving.value=false;}}
/** 初始化稳定数据候选草稿。 Initialize a stable dataset candidate draft. */
function beginCandidate(){candidate.value=true;name.value=(detail.value.name||'实验')+' · 数据候选';purpose.value='';pendingCandidate.value=null;}
/** 保存本地候选，超时保留同一身份与参数。 Save a local candidate and retain its identity after timeout. */
async function saveCandidate(){if(saving.value||!detail.value)return;if(!pendingCandidate.value)pendingCandidate.value=Object.freeze({episodeId:detail.value.id,key:'candidate-'+crypto.randomUUID(),body:JSON.stringify({name:name.value,purpose:purpose.value})});const pending=pendingCandidate.value;saving.value=true;detailError.value='';try{await request('/episodes/'+encodeURIComponent(pending.episodeId)+'/dataset-candidates',props.project,{method:'POST',headers:{'Idempotency-Key':pending.key},body:pending.body});pendingCandidate.value=null;candidate.value=false;notice.value='数据候选已保存，可在数据交接页查看。尚未提交到 DataOps。';emit('candidate');}catch(cause){if(cause.status>=400&&cause.status<500&&cause.status!==408)pendingCandidate.value=null;detailError.value=cause.message;}finally{saving.value=false;}}
/** 撤销数据候选填写，不影响封存实验。 Cancel candidate input without modifying the sealed episode. */
function cancelCandidate(){if(canLeave())candidate.value=false;}
/** 最多选择两个已封存实验用于同环境比较。 Select at most two sealed experiments for comparison. */
function choose(item,event){const id=props.kind==='runs'?item.episodeId:item.id;if(loading.value){event.target.checked=selected.value.includes(id);return;}comparison.value=null;if(event.target.checked){if(selected.value.length===2){event.target.checked=false;notice.value='每次选择两个实验进行比较。';return;}selected.value.push(id);}else selected.value=selected.value.filter(removeId);/** 移除取消选择的实验。 Remove the deselected experiment. */function removeId(value){return value!==id;}}
/** 比较相同环境和版本的真实计数与内部规则。 Compare actual counts and internal rules for the same environment version. */
async function compare(){if(selected.value.length!==2||loading.value)return;const ticket=++generation;loading.value=true;error.value='';try{const results=await Promise.all(selected.value.map(readEpisode));if(ticket!==generation)return;if(results[0].environmentId!==results[1].environmentId||results[0].environmentVersion!==results[1].environmentVersion||results[0].executionMode!==results[1].executionMode)throw new Error('请选择相同环境、环境版本与执行模式的两条实验记录');comparison.value=results;}catch(cause){if(ticket===generation)error.value=cause.message;}finally{if(ticket===generation)loading.value=false;}}
/** 按授权项目读取单个比较对象。 Read one comparison subject in the authorized project. */
function readEpisode(id){return request('/episodes/'+encodeURIComponent(id),props.project);}
/** 显示内部验收的三态，缺失结果保持未知。 Display tri-state internal verification without assuming missing results. */
function verification(item){return item.verification?.success===true?'内部规则通过':item.verification?.success===false?'内部规则未通过':'暂无验证结论';}
/** 从实际事件中提取概要，不合成执行结果。 Extract event summaries without synthesizing execution. */
function eventSummary(item){const body=item.payload||item;if(item.type==='receipt')return body.executed===true?'已执行，结果需独立核验':body.executed===false?'未执行':'执行状态未提供';return body.skill_id?phase(body.skill_id):body.observation_id||body.action_chunk_id||'已封存事件';}
/** 使用契约原始字段展示业务摘要，接收与执行分别说明。 Present contract fields with acceptance and execution stated separately. */
function eventFields(item){const body=item.payload||{};if(item.type==='action')return [['任务阶段',phase(body.skill_id)],['预计时长（毫秒）',displayValue(body.duration_ms)],['策略版本',displayValue(body.policy_version)],['前置条件',body.preconditions?.length?body.preconditions.join('、'):'未声明'],['最大移动速度（米/秒）',displayValue(body.safety_limits?.max_cartesian_speed_mps)],['观测时效上限（毫秒）',displayValue(body.safety_limits?.observation_max_age_ms)]];if(item.type==='receipt')return [['动作已被接收',displayValue(body.accepted)],['动作已被执行',displayValue(body.executed)],['回执标识',displayValue(body.receipt_id)],['关联动作',displayValue(body.action_chunk_id)],['失败说明',body.error?.message||body.error?.code||'未提供'],['验证边界','执行回执不替代独立结果核验']];return [['观测标识',displayValue(body.observation_id)],['序列',displayValue(body.sequence)],['采集时间（纳秒）',displayValue(body.timestamp_ns)],['来源坐标',displayValue(body.frame_id)]];}
/** 离页后失效所有读取。 Invalidate all reads after leaving. */
function dispose(){++generation;++detailGeneration;++eventGeneration;}
onMounted(reload);onBeforeUnmount(dispose);defineExpose({canLeave});
</script>
<template>
<section class="collection-panel evidence-page"><div class="section-heading"><div><h2>{{title}}</h2><p>{{kind==='actions'?'沿记录核对候选动作、执行回执和结果，保留每一步原始证据。':'按来源与版本查找实验，把每一次运行变成可复用的依据。'}}</p></div><button class="primary-button" @click="emit('studio')">＋ 开始实验</button></div><form class="filter-bar" @submit.prevent="reload"><label class="search-field"><span class="sr-only">搜索实验</span><input v-model="query" maxlength="100" placeholder="搜索名称或记录标识"></label><select v-model="filter" aria-label="记录筛选" @change="reload"><option value="">全部{{kind==='runs'?'状态':'模式'}}</option><template v-if="kind==='runs'"><option value="succeeded">运行完成</option><option value="failed">运行失败</option><option value="interrupted">运行中断</option><option value="running">计算中</option></template><template v-else><option value="simulation">内部仿真</option><option value="replay">历史回放</option><option value="live">真实执行</option></template></select><button class="secondary-button" type="submit" :disabled="loading">查询</button><button v-if="kind!=='actions'" class="secondary-button" type="button" :disabled="selected.length!==2||loading" @click="compare">比较所选 {{selected.length}} / 2</button></form>
<p v-if="error" class="message error" role="alert">{{error}}<button @click="reload">重试</button></p><p v-if="notice" class="message notice" role="status">{{notice}}</p>
<div v-if="comparison" class="comparison-panel"><h3>相同环境版本 · 实验对照</h3><div class="table-scroll"><table><thead><tr><th>记录</th><th>观测</th><th>动作</th><th>回执</th><th>内部验收</th></tr></thead><tbody><tr v-for="item in comparison" :key="item.id"><td>{{item.name}}<small>{{item.id}}</small></td><td>{{item.observationCount??'未提供'}}</td><td>{{item.actionCount??'未提供'}}</td><td>{{item.receiptCount??'未提供'}}</td><td>{{verification(item)}}</td></tr></tbody></table></div><p class="form-note">此处对照封存计数及内部规则，不替代独立评测。</p></div>
<div v-if="loading&&!rows.length" class="empty" role="status">正在读取记录…</div><div v-else-if="!rows.length" class="empty"><span class="empty-symbol">≋</span><h3>{{error?'记录暂不可用':'还没有符合条件的记录'}}</h3><p>更换查询条件，或从空间实验台完成第一次仿真。</p><button class="secondary-button" @click="emit('studio')">前往空间实验台</button></div>
<div v-else class="table-scroll"><table><thead><tr><th v-if="kind!=='actions'">对照</th><th>{{kind==='runs'?'运行':'实验记录'}}</th><th>模式</th><th>{{kind==='runs'?'种子':'观测 / 动作 / 回执'}}</th><th>状态</th><th>记录时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td v-if="kind!=='actions'"><input type="checkbox" :aria-label="'选择比较 '+item.id" :disabled="loading||kind==='runs'&&!item.episodeId" :checked="selected.includes(kind==='runs'?item.episodeId:item.id)" @change="choose(item,$event)"></td><td class="cell-title">{{item.name||'物体交接仿真'}}<small>{{item.id}}</small><span v-if="item.error" class="run-error">{{item.error.message}}</span></td><td>{{displayValue(item.executionMode)}}</td><td>{{kind==='runs'?item.seed:`${item.observationCount??'—'} / ${item.actionCount??'—'} / ${item.receiptCount??'—'}`}}</td><td>{{kind==='runs'?displayValue(item.status):verification(item)}}</td><td>{{displayValue(item.startedAt||item.createdAt,'createdAt')}}</td><td><button class="quiet-button" :disabled="kind==='runs'&&!item.episodeId" @click="open(item)">{{kind==='actions'?'查看动作与回执':'查看记录'}} ↗</button><small v-if="kind==='runs'&&!item.episodeId">{{item.status==='running'?'计算完成后可查看':'未生成实验记录'}}</small></td></tr></tbody></table></div><div class="pagination-bar"><span>{{total===null?'总数未提供':`已载入 ${rows.length} / ${total} 条`}}</span><button v-if="cursor" class="secondary-button" :disabled="loading" @click="more">载入下一页</button></div></section>
<PanelDialog v-if="dialog" :title="candidate?'创建数据候选':detail?.name||'实验详情'" :busy="saving" @close="close"><p v-if="detailLoading" role="status">正在读取封存记录…</p><p v-if="detailError" class="message error" role="alert">{{detailError}}</p><template v-if="detail"><form v-if="candidate" id="candidate-form" class="record-form" @submit.prevent="saveCandidate"><label>候选名称<input v-model="name" maxlength="100" required :disabled="saving||!!pendingCandidate"></label><label>数据用途<textarea v-model="purpose" maxlength="500" rows="5" required :disabled="saving||!!pendingCandidate" placeholder="例如：评估双臂交接任务的动作与观测一致性"></textarea></label><p v-if="pendingCandidate&&!saving" class="message notice" role="status">保存结果尚未确认，已保留原始名称和用途。再次保存会确认同一候选。</p><p class="form-note">来源：{{detail.id}}。仅创建项目内候选，保留来源版本与摘要。</p></form><template v-else><div class="evidence-summary"><span class="mode-badge">{{displayValue(detail.executionMode)}}</span><h3>{{verification(detail)}}</h3><p>{{detail.id}}</p><div class="evidence-counts"><div><b>{{detail.observationCount??'—'}}</b>观测</div><div><b>{{detail.actionCount??'—'}}</b>动作</div><div><b>{{detail.receiptCount??'—'}}</b>回执</div></div></div><details class="structured-details"><summary>来源、版本与内部验证依据</summary><dl class="detail-grid"><div><dt>环境标识</dt><dd>{{detail.environmentId}}</dd></div><div><dt>环境版本</dt><dd>{{detail.environmentVersion}}</dd></div><div><dt>内容摘要</dt><dd>{{detail.contentDigest}}</dd></div><div><dt>封存时间</dt><dd>{{displayValue(detail.completedAt,'completedAt')}}</dd></div></dl><pre>{{JSON.stringify(detail.verification,null,2)}}</pre></details><div class="section-heading event-heading"><h3>事件记录</h3><select v-model="eventType" aria-label="事件类型" @change="filterEvents"><option value="">全部事件</option><option value="observation">环境观测</option><option value="action">候选动作</option><option value="receipt">执行回执</option></select></div><p v-if="eventLoading&&!events.length" role="status">正在读取事件…</p><p v-if="!eventLoading&&!events.length" class="inline-empty">暂无此类型的事件记录。</p><ol class="event-list"><li v-for="item in events" :key="item.sequence"><span class="event-sequence">{{item.sequence}}</span><details><summary><b>{{displayValue(item.type)}}</b><span>{{displayValue(eventSummary(item))}}</span></summary><dl class="detail-grid"><div v-for="[label,value] in eventFields(item)" :key="label"><dt>{{label}}</dt><dd>{{value}}</dd></div></dl><details class="structured-details"><summary>查看完整原始事件</summary><pre>{{JSON.stringify(item,null,2)}}</pre></details></details></li></ol><div class="pagination-bar"><span>{{events.length}} / {{eventTotal??'—'}} 条事件</span><button v-if="eventCursor" class="secondary-button" :disabled="eventLoading" @click="moreEvents">更多事件</button></div></template></template><template #footer><button class="secondary-button" :disabled="saving" @click="candidate?cancelCandidate():close()">{{candidate?'返回详情':'关闭'}}</button><button v-if="candidate" class="primary-button" type="submit" form="candidate-form" :disabled="saving">{{saving?'保存中…':pendingCandidate?'重试确认同一候选':'保存数据候选'}}</button><template v-else-if="detail"><button class="secondary-button" :disabled="saving" @click="exportEpisode">导出索引</button><button class="secondary-button" :disabled="saving" @click="beginCandidate">创建数据候选</button><button class="primary-button" :disabled="saving" @click="replay">打开空间回放 ↗</button></template></template></PanelDialog>
</template>
